 if(fx.gears){const amount=states[0]?.progress||0;fx.gears.forEach((g,i)=>g.rotation.z=(i?1:-1)*(amount*Math.PI*8+time*power*1.4));fx.windKey.rotation.z=-amount*Math.PI*4;fx.hourHand.rotation.z-=dt*power*.055;fx.minuteHand.rotation.z-=dt*power*.66;fx.bells.forEach((b,i)=>b.rotation.z=b.userData.rest+Math.sin(time*24+i)*power*.07);}
